      write(doc, model.serviceCodeDescription, LEFT, y + 0.06, CONTENT_WIDTH, { color: "#555555" });
      y += 0.4;
      write(doc, "Descri\xE7\xE3o do Servi\xE7o", LEFT, y, CONTENT_WIDTH, { font: BOLD, size: 6 });
      doc.font(REGULAR).fontSize(7);
